/*	Render Page - builds the offer page. GET only, and this workflow writes nothing,
	so a mail scanner following the link cannot answer on somebody\u2019s behalf. Recording
	happens in Waitlist 02 - Response Handler, on POST.	*/

const cfg_obj = $('Config').first().json;
const link_obj = $('Extract Link').first().json;
const api_obj = $input.first().json;
const now_str = $now.toISO();

const rows_ary = $('Load Row').all().map(function (i_obj) { return i_obj.json; }).filter(function (r_obj) { return r_obj && r_obj.token; });
const row_obj = rows_ary.find(function (r_obj) { return String(r_obj.token) === String(link_obj.offerToken); }) || null;

const event_obj = ((((api_obj.data || {}).events || {}).edges || [])[0] || {}).node || null;

const esc_fn = function (v_any)
{
	return String(v_any === null || v_any === undefined ? '' : v_any)
		.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
};

const pretty_fn = function (iso_str)
{
	if (!iso_str) { return ''; }
	const d_obj = new Date(String(iso_str).replace(' ', 'T'));
	if (isNaN(d_obj.getTime())) { return String(iso_str); }
	const months_ary = ['January','February','March','April','May','June','July','August','September','October','November','December'];
	return d_obj.getDate() + ' ' + months_ary[d_obj.getMonth()] + ' ' + d_obj.getFullYear();
};

const prettyTime_fn = function (iso_str)
{
	if (!iso_str) { return ''; }
	const d_obj = new Date(String(iso_str).replace(' ', 'T'));
	if (isNaN(d_obj.getTime())) { return ''; }
	const h_str = String(d_obj.getHours()).padStart(2, '0');
	const m_str = String(d_obj.getMinutes()).padStart(2, '0');
	return pretty_fn(iso_str) + ' at ' + h_str + ':' + m_str;
};

const page_fn = function (title_str, body_str)
{
	return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc_fn(title_str) + '</title><style>' + cfg_obj.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc_fn(cfg_obj.BRAND_NAME) + '</p></header><main>' + body_str + '</main></body></html>';
};

/*	Two shapes of page that are not the form, and they are not the same thing.
	refuse is for something genuinely wrong, so it ends by pointing at a human.
	closeOff is for when everything is in order and there is simply nothing to do	*/
const refuse_fn = function (heading_str, message_str)
{
	return [{ json: { html: page_fn(heading_str, '<h1>' + esc_fn(heading_str) + '</h1><div class="notice error"><p>' + esc_fn(message_str) + '</p></div><p>Please reply to the offer email and someone will help.</p>') } }];
};

const closeOff_fn = function (heading_str, message_str)
{
	return [{ json: { html: page_fn(heading_str, '<h1>' + esc_fn(heading_str) + '</h1><div class="notice"><p>' + esc_fn(message_str) + '</p></div><p>You can close this page.</p>') } }];
};

if (!row_obj)
{
	return refuse_fn('This link is no longer valid', 'We could not find this offer. It may have been withdrawn, or the link may be incomplete.');
}

const title_str = String(row_obj.event_title || (event_obj || {}).title || 'this event');
const status_str = String(row_obj.status || '');

if (status_str === 'accepted')
{
	return closeOff_fn('You have already accepted', 'Your place on ' + title_str + ' is confirmed. Nothing further is needed.');
}

if (status_str === 'declined')
{
	return closeOff_fn('You have already declined', 'We recorded that you did not want this place, and it has been offered to somebody else. If that has changed, reply to the offer email and we will pick it up.');
}

if (status_str === 'expired' || (row_obj.expires_at && DateTime.fromISO(String(row_obj.expires_at)) < DateTime.fromISO(now_str)))
{
	return closeOff_fn('This offer has expired', 'The place was held for a limited time and has now passed to the next person on the waitlist.');
}

if (status_str !== 'offered')
{
	return refuse_fn('This link is no longer valid', 'This offer is not open for a response.');
}

/*	Capacity is read at the moment of the click. The handler re-checks it again at submit
	time, because somebody else can accept in between	*/
const max_num = Number((event_obj || {}).maxPlaces || 0);
const reg_num = Number(((((event_obj || {}).learners || {}).pageInfo || {}).totalRecords) || 0);

if (event_obj && max_num > 0 && reg_num >= max_num)
{
	return closeOff_fn('This event is now full', 'Somebody else took the last place before we heard from you, so this offer can no longer be honoured. Thank you for considering it.');
}

const when_str = pretty_fn((event_obj || {}).start);
const where_str = ((event_obj || {}).location || {}).name || '';

const meta_str = '<p class="meta">'
	+ (when_str ? '<span>' + esc_fn(when_str) + '</span>' : '')
	+ (when_str && where_str ? ' &middot; ' : '')
	+ (where_str ? '<span>' + esc_fn(where_str) + '</span>' : '')
	+ '</p>';

const hold_str = row_obj.expires_at
	? '<p class="hold">This place is held for you until ' + esc_fn(prettyTime_fn(String(row_obj.expires_at))) + '. After that it passes to the next person on the waitlist.</p>'
	: '';

/*	Two submit buttons rather than two links. A scanner fetching this page cannot press
	one, which is the whole reason the recording lives behind a POST	*/
const body_str = '<h1>A place is available on ' + esc_fn(title_str) + '</h1>'
	+ meta_str
	+ '<div class="notice"><p>A place has opened on this course, and you are next on the waitlist. Let us know either way and we will do the rest.</p></div>'
	+ '<form method="post" action="' + esc_fn(cfg_obj.SUBMIT_URL) + '">'
	+ '<input type="hidden" name="token" value="' + esc_fn(row_obj.token) + '">'
	+ '<div class="actions">'
	+ '<button type="submit" class="primary" name="action" value="' + esc_fn(cfg_obj.ACCEPT_ACTION) + '">' + esc_fn(cfg_obj.ACCEPT_LABEL) + '</button>'
	+ '<button type="submit" class="secondary" name="action" value="' + esc_fn(cfg_obj.DECLINE_ACTION) + '">' + esc_fn(cfg_obj.DECLINE_LABEL) + '</button>'
	+ '</div></form>'
	+ hold_str;

return [{ json: { html: page_fn('A place is available', body_str) } }];
